"""Build a self-contained Korean adoption site from versioned content."""
from pathlib import Path
from html import escape
from pr_faq_pages import build_pr_faq

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'site'
URL = 'https://roboco.io/govcode-harness-guide/'
REPO = 'https://github.com/roboco-io/govcode-harness'
CODE_REF = 'v0.10.0'
TAG = REPO + '/tree/' + CODE_REF
FILES = REPO + '/blob/' + CODE_REF

def code(text):
    return '<div class="codebox"><button type="button" data-copy aria-label="명령 복사">복사</button><pre><code>' + escape(text.strip()) + '</code></pre></div>'

def table(headers, rows):
    return '<div class="table-scroll"><table><thead><tr>' + ''.join('<th scope="col">'+x+'</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows) + '</tbody></table></div>'

def flow():
    return '''<ol class="flow" aria-label="민원 API 변경 검사 흐름">
<li><span class="number">1</span><span>민원 본문을 로그에 기록하는 코드</span><span class="state deny">deny</span></li>
<li><span class="number">2</span><span>원문 로깅 제거 · 감사 이벤트 유지</span><span class="state">수정</span></li>
<li><span class="number">3</span><span>새 commit의 필수 검사 재실행</span><span class="state allow">allow</span></li>
<li><span class="number">4</span><span>정책·판정·수정 이력을 증적으로 연결</span><span class="state">증적</span></li></ol>'''

def platform_flow():
    return '<ol class="flow platform-flow" aria-label="제품 목표: 공공 프로젝트 규정 충족 흐름"><li><span class="number">1</span><span>우리 업무에 필요한 기준 확인</span><span class="state">기준</span></li><li><span class="number">2</span><span>해야 할 일과 담당자 정리</span><span class="state">작업</span></li><li><span class="number">3</span><span>문제를 점검하고 수정 결과 확인</span><span class="state">점검</span></li><li><span class="number">4</span><span>검토한 사람과 확인 자료 기록</span><span class="state">기록</span></li></ol>'

def page(name, title, description, body):
    links = [('index.html','프로젝트 소개'),('start.html','쉬운 안내'),('brochure.html','소개 자료'),('pr.html','PR'),('faq.html','FAQ'),('community.html','의견·참여'),('updates.html','업데이트'),('onboarding.html','설치·실행')]
    nav = ''.join('<a href="'+path+'"'+(' aria-current="page"' if path==name else '')+'>'+label+'</a>' for path,label in links)
    text = '''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>'''+escape(title)+''' | GovCode Harness</title><meta name="description" content="'''+escape(description)+'''">
<meta name="theme-color" content="#142943"><link rel="license" href="https://creativecommons.org/licenses/by/4.0/"><link rel="canonical" href="'''+URL+name+'''">
<meta property="og:title" content="'''+escape(title)+''' | GovCode Harness"><meta property="og:description" content="'''+escape(description)+'''">
<meta property="og:type" content="website"><meta property="og:locale" content="ko_KR"><meta property="og:url" content="'''+URL+name+'''">
<script src="assets/theme.js"></script><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script defer src="assets/site.js"></script></head>
<body><a class="skip" href="#main">본문 바로가기</a><header class="top"><div class="wrap"><a class="brand" href="index.html"><span class="mark" aria-hidden="true">G</span>GovCode Harness</a><div class="header-tools"><a class="repo-link" href="https://github.com/roboco-io/govcode-harness" aria-label="프로젝트 GitHub"><svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false" fill="currentColor"><path d="M12 .75a11.25 11.25 0 0 0-3.56 21.92c.56.1.77-.24.77-.54v-2.1c-3.13.68-3.79-1.33-3.79-1.33-.51-1.3-1.25-1.65-1.25-1.65-1.02-.7.08-.69.08-.69 1.13.08 1.73 1.16 1.73 1.16 1 1.72 2.64 1.22 3.28.93.1-.73.39-1.22.71-1.5-2.5-.29-5.13-1.25-5.13-5.56 0-1.23.44-2.23 1.16-3.01-.12-.29-.5-1.43.11-2.98 0 0 .95-.3 3.1 1.15a10.8 10.8 0 0 1 5.63 0c2.15-1.46 3.1-1.15 3.1-1.15.61 1.55.23 2.69.11 2.98.72.78 1.16 1.78 1.16 3.01 0 4.32-2.64 5.27-5.15 5.55.4.35.76 1.03.76 2.08v3.11c0 .3.2.65.77.54A11.25 11.25 0 0 0 12 .75Z"/></svg><span>GitHub</span></a><button class="theme-toggle" type="button" data-theme-toggle aria-label="다크 모드로 전환"><svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="8" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="M12 4a8 8 0 0 1 0 16Z" fill="currentColor"/></svg><span data-theme-label>다크</span></button><button class="theme-system" type="button" data-theme-system aria-label="기기 설정 사용" title="기기 설정 사용" hidden>자동</button></div><nav class="nav" aria-label="주 메뉴">'''+nav+'''</nav></div></header>
'''+body+'''<footer class="footer"><div class="wrap"><p>GovCode Harness · 보안이 내재화된 개발 하네스 · 시험·개선 중인 파일럿 단계 · v0.10.0 프리뷰<br>프리뷰 안내 기준: 2026-10-30. 검사 통과는 법적 준수 인증이나 기관 운영 승인을 뜻하지 않습니다.<br>© 2026 GovCode Harness contributors · 가이드·브로슈어 <a rel="license" href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a> · <a href="license.html">출처 표시 안내</a> · 프로젝트 코드 <a href="https://github.com/roboco-io/govcode-harness/blob/main/LICENSE">Apache-2.0</a></p><a href="'''+REPO+'''">프로젝트 GitHub</a></div></footer><div class="sr-only" id="status" role="status" aria-live="polite"></div></body></html>'''
    (SITE/name).write_text(text)

def build():
    page('index.html','보안이 내재화된 개발 하네스','보안 기준을 개발 흐름에 연결합니다. 코드 검사부터 수정 지원·담당자 승인·증적까지, 공공 프로젝트를 위한 개발 하네스를 만나보세요.',
'''<main id="main"><div class="wrap"><section class="hero"><div><span class="tag">공공 프로젝트를 위한 GovCode Harness</span><h1>보안이 내재화된<br>개발 하네스</h1><p class="lead">다양한 공공 프로젝트에서 비개발자가 AI와 함께 업무 도구를 안전하게 만들도록 돕는 것이 목표입니다. 원하는 일을 설명하고, 만든 결과를 시험·수정하며, 필요한 검토와 승인을 받는 과정에 보안 점검을 연결합니다.</p><div class="actions"><a class="button" href="start.html">설치 없이 이해하기</a><a class="button secondary" href="brochure.html">소개 자료 보기</a></div><p class="caption">시험·개선 중인 파일럿 단계 · Apache-2.0 조건에 따라 무상 사용 가능<br>v0.10.0 프리뷰 공개 · 사업 정보·규정 묶음·설계 문서 초안 지원</p></div><div class="dossier"><p class="dossier-title">프로젝트가 지향하는 업무 흐름</p>'''+platform_flow()+'''<p class="small">‘하네스’는 여러 개발 도구와 점검 절차를 연결해 함께 작동하게 하는 장치입니다. 현재는 민원 내용이 불필요한 기록에 남는 문제를 첫 사례로 확인했습니다.</p></div></section>
<div class="proof-strip" aria-label="검증과 지원 범위"><p><strong>설치 없이 먼저 살펴보세요</strong>쉬운 설명과 화면 예시 제공</p><p><strong>의견만 남겨도 참여입니다</strong>개발 경험 없이도 참여 가능</p><p><strong>현재는 시험·개선 단계</strong>실제 업무 도입은 별도 검토 필요</p></div></div>
<section class="section"><div class="wrap"><div class="section-head"><h2>개발하는 순간부터,<br>보안 기준이 작동하도록.</h2><p>개발자는 수정할 지점을, 보안 담당자는 판단할 근거를, 프로젝트 책임자는 남은 작업을 알아야 합니다. GovCode Harness는 각자의 업무를 하나의 개발 흐름으로 연결하는 것을 지향합니다.</p></div><div class="columns"><article class="feature"><h3>개발자에게는 다음 행동을</h3><p>점검에서 발견한 문제를 고치고 다시 확인하도록 돕습니다. 첫 사례에서는 민원 원문을 불필요하게 기록하는 코드를 찾아, 수정한 코드가 검사를 통과하는지 확인했습니다.</p></article><article class="feature"><h3>검토자에게는 판단 근거를</h3><p>어떤 기준으로 점검했고 누가 검토했는지 확인합니다. 첫 사례에서는 작성자와 승인자를 나누고, 검사 결과의 출처와 변경 여부를 확인할 수 있는 기록을 남겼습니다.</p></article><article class="feature"><h3>책임자에게는 진행 상황을</h3><p>점검과 수정이 어떻게 진행됐는지 관리 화면에서 확인합니다. 프로젝트 전체에서 끝난 일, 검토 중인 일, 아직 확인하지 못한 일을 한눈에 보는 기능은 앞으로 확장할 계획입니다.</p></article></div></div></section>
<section class="section wash"><div class="wrap"><div class="section-head"><h2>보안에서 시작해,<br>공공 프로젝트의 요구까지.</h2><p>v0.10.0 프리뷰에 프로젝트 정보 관리, 규정 묶음 발행·적용 대상 판단과 설계 문서 초안 생성이 포함됐습니다. 아래 분야의 실제 점검과 전체 충족 현황 안내는 후속 범위입니다. <a href="updates.html">공개 버전과 개발 상황 보기</a></p></div><div class="columns"><div><h3>개인정보·보안 / 접근성</h3><p>보호 요구와 이용 환경별 점검을 작업·수정·검토 근거에 연결하는 방향입니다.</p></div><div><h3>개발 품질 / 표준·상호운용성</h3><p>필수 시험과 프로젝트별 개발·인터페이스 기준을 확인하도록 확장합니다.</p></div><div><h3>사업 산출물 / 운영·보존</h3><p>단계별 문서·검수·운영·보존 요구와 제출 근거를 안내하도록 확장합니다.</p></div></div><div class="note"><p><strong>특정 업무에 한정하지 않습니다.</strong> 민원 로깅은 점검·수정 흐름을 확인한 첫 기술 사례입니다. 이번 프리뷰는 여러 공공 프로젝트에 적용할 사업 정보와 규정 묶음, 문서 작성 기반을 확장했습니다. <a href="start.html#example">이 사례를 쉬운 설명으로 읽어 보세요.</a></p></div></div></section><section class="section wash"><div class="wrap split"><div><h2>개발과 검토가<br>같은 근거로 이어집니다.</h2><p>한국어 관리 화면에서 점검 기준과 결과, 수정 과정을 확인할 수 있습니다. 담당 업무에 따라 볼 수 있는 자료와 승인할 수 있는 일이 달라집니다.</p><ul class="capability"><li>기관·프로젝트·담당 업무에 따라 자료 열람 권한 구분</li><li>시험용 계정으로 작성·승인·운영·검토 역할 확인</li><li>확인 자료의 변경·삭제 제한과 사본 보관·복구</li></ul><p class="small">화면은 가상 자료와 시험용 계정으로 만든 예시입니다. 실제 기관의 직원 계정 연결은 별도 작업이 필요합니다.</p></div><figure style="margin:0"><img class="screenshot" src="assets/images/control-desk.png" alt="합성 감사 열람자의 GovCode 관리 화면. 실행 결과와 증적 조회 메뉴를 보여 줍니다." loading="lazy" width="1440" height="1000"><figcaption class="caption">시험 버전 관리 화면 · 가상 자료</figcaption></figure></div></section>
<section class="section"><div class="wrap"><div class="section-head"><h2>파일럿을 함께 경험하고,<br>다음 개발 흐름을 만들어 주세요.</h2><p>프로젝트 코드는 Apache-2.0 조건에 따라 개인·기관·기업이 라이선스 비용이나 로열티 없이 사용·수정·재배포할 수 있습니다. 상업적 이용도 가능합니다.</p></div><p>현재는 가상 자료로 작동 과정을 확인하는 프리뷰입니다. 비개발자가 직접 만들고 싶은 업무 도구와 필요한 점검을 알려 주세요. 자연어 요구부터 제작·실행·공유까지 이어지는 전체 경험과 실제 기관 시험 운영은 아직 완성되지 않았습니다.</p><p class="small">재배포 시 라이선스·저작권·NOTICE·수정 사실 표시 등 조건을 준수해야 합니다. 무보증 조건이 적용되며 설치·인프라·운영 비용은 사용 환경에 따라 발생할 수 있습니다. 가이드·브로슈어는 CC BY 4.0입니다. <a href="license.html">라이선스 안내</a></p><div class="actions"><a class="button" href="community.html">피드백·기여 방법 보기</a><a class="button secondary" href="https://github.com/roboco-io/govcode-harness/issues/new?template=01-feedback.yml">파일럿 피드백 남기기</a></div></div></section><section class="section"><div class="wrap"><div class="section-head"><h2>첫 도입은 작게.<br>다음 결정은 근거 있게.</h2><p>먼저 사례와 화면을 읽어 보고 우리 업무에서 필요한 점검을 정리하세요. 직접 실행해 보고 싶다면 개발 담당자에게 설치·실행 안내를 전달해 주세요.</p></div><div class="boundaries"><div><h3>지금 실행할 수 있는 것</h3><p>시험용 프로그램의 문제 발견과 수정 후 재점검, 담당자 승인, 확인 자료의 보관과 복구를 개발 담당자의 컴퓨터에서 시험할 수 있습니다.</p></div><div><h3>도입 전에 확정할 것</h3><p>우리 기관에 적용할 기준, 참여할 담당자, 사용할 자료와 보관 방법, 시험 범위를 개발·보안 담당자와 함께 정해야 합니다.</p></div></div><div class="note"><p><strong>지원 경계</strong> 현재는 Python이라는 개발 언어의 일부 코드만 점검하며, 전체 시험은 macOS에서 확인했습니다. AI는 미리 준비한 응답으로 동작을 시험했습니다. 실제 AI의 답변 품질은 아직 확인하지 않았습니다.</p></div><div class="actions"><a class="button" href="start.html#next">내 역할에 맞는 다음 단계</a><a class="button secondary" href="downloads/govcode-harness-brochure.pdf" download>소개 자료 PDF 받기</a><a href="'''+TAG+'''">v0.10.0 코드 보기</a></div></div></section></main>''')

    get_source=code('''git clone --branch v0.10.0 --depth 1 https://github.com/roboco-io/govcode-harness.git
cd govcode-harness''')
    basic=code('''python3 -m govcode_harness demo --output .runtime/first-onboarding''')
    setup=code(r'''python3 scripts/setup_reference.py \
  --python /absolute/path/to/python3.12 \
  --uv /absolute/path/to/uv''')
    reference=code(r'''.runtime/reference-venv/bin/python -m govcode_harness reference-demo \
  --output .runtime/onboarding-reference''')
    control=code(r'''.runtime/reference-venv/bin/python -m govcode_harness control \
  --config .runtime/onboarding-reference/control-config.json \
  --port 8766''')
    inspect=code('''python3 -m json.tool .runtime/onboarding-reference/reference-result.json''')
    tests=code('''.runtime/reference-venv/bin/python -m unittest discover -s tests -p 'test_*.py' -q
.runtime/reference-venv/bin/python -m govcode_harness gate --help''')
    checklist=''.join('<li><label><input type="checkbox"><span>'+item+'</span></label></li>' for item in [
      '대상 저장소·Python 지원 구문·제외 범위를 정했습니다.',
      '개인정보·보안 담당자와 규정 적용성 및 미확정 항목을 확인했습니다.',
      '정책 작성자·승인자·운영자·감사 열람자와 운영 신원을 정했습니다.',
      '서명키·신뢰 루트·철회 전파·최소 순번 관리 책임을 정했습니다.',
      '증적 보존 분류·접근·보관 잠금·파기·복구 책임을 정했습니다.',
      'CI의 신뢰한 expected commit과 필수 검사·보호 브랜치 설정을 정했습니다.',
      '모델 사용 여부와 허용 입력·반출 범위를 정했습니다.',
      '파일럿 기간·표본·정답·성공 기준·중단 조건·책임자를 정했습니다.'])
    page('onboarding.html','개발 담당자용 설치·실행 안내','소스 받기부터 기본 데모, 서명 참조 실행, 관리 화면과 실제 기관 파일럿 준비까지 단계별로 안내합니다.',
'''<main id="main" class="wrap"><header class="page-head"><span class="tag">파일럿 단계 · v0.10.0 프리뷰 도입 안내</span><h1>개발 담당자를 위한<br>설치·실행 안내</h1><p>이 페이지는 개발 도구를 설치하고 명령을 실행하는 담당자를 위한 안내입니다. 프로젝트를 처음 살펴보신다면 <a href="start.html">설치 없이 읽는 쉬운 안내</a>부터 보세요. 아래 절차는 시험용 민원 프로그램을 점검하는 방법입니다.</p></header><div class="guide-grid"><nav class="toc" aria-label="가이드 목차"><strong>처음 시작하는 순서</strong><a href="#project-scope">우리 팀의 개발 흐름부터</a><a href="#prepare">1. 준비와 지원 범위</a><a href="#source">2. 소스 받기</a><a href="#basic">3. 기본 흐름 확인</a><a href="#reference">4. 전체 참조 실행</a><a href="#preview">새 기능: 프로필·규정 팩·문서</a><a href="#results">5. 기존 참조 결과 읽기</a><a href="#control">6. 관리 화면 열기</a><a href="#ci">7. CI 적용 준비</a><a href="#pilot">8. 기관 파일럿 준비</a><a href="#troubleshooting">문제 해결</a><a href="#evidence">검증 근거와 자료</a></nav><article class="article">
<div class="note"><p><strong>파일럿에 참여해 주세요.</strong> 본 프로젝트는 Apache-2.0 조건에 따라 라이선스 비용이나 로열티 없이 사용할 수 있습니다. 실행 경험이나 문서 의견은 <a href="community.html">피드백·기여 안내</a>에서 남겨 주세요.</p></div><section id="project-scope"><h2>우리 팀의 개발 흐름부터 살펴보세요</h2><p>보안이 내재화된 개발 하네스는 팀의 보안 기준을 작업·검사·수정 지원·승인·증적으로 연결하는 실행 기반입니다. GovCode Harness는 이를 공공 프로젝트에 적용하는 것을 지향합니다. 먼저 다음 질문으로 도입 범위를 정리하세요.</p><ol><li>어떤 개발 단계와 저장소에 적용할까요? 프로젝트 유형·기관 조건·적용 후보 기준을 정리합니다.</li><li>개발팀이 무엇을 해야 할까요? 기준의 출처·버전·적용 조건을 확인하고 작업·산출물·담당자를 연결합니다.</li><li>어디까지 자동화할까요? 검사·수정 지원과 담당자 판단·승인의 역할을 정합니다.</li><li>무엇을 완료 근거로 삼을까요? 검사 결과·검토 기록·증적과 다음 작업을 정합니다.</li></ol><div class="note"><p><strong>목표와 현재 기능</strong> 공개 v0.10.0 프리뷰에 프로젝트 프로필·규정 팩 발행·적용성 판단·설계 문서 초안 생성이 포함됐습니다. 산출물 검사와 전체 충족 현황은 후속 범위입니다. 아래 명령은 이 공개 태그를 기준으로 합니다. <a href="updates.html">개발 상태와 공개 범위 확인</a></p></div><p><a href="https://github.com/roboco-io/govcode-harness/blob/main/docs/PRODUCT_DIRECTION.md">제품 전체 범위와 다음 설계</a></p></section><section id="prepare"><h2>1. 준비와 지원 범위</h2><p>개발자 또는 플랫폼 담당자가 로컬 환경에서 시작할 수 있습니다. 실제 민원 원문·운영 비밀값을 준비할 필요가 없습니다.</p>'''+table(['경로','필요 환경','확인하는 것'],[
['기본 데모','Python 3.10 이상, Git','표준 라이브러리 경로의 탐지·차단·수정·재검사. 서명 없음.'],
['전체 참조 데모','macOS, Python 3.12 이상, Git, uv, sandbox-exec 사용 가능 환경','서명 정책·격리 수정·증적·보관·복구·관리 API. 로컬 HTTP와 프로세스 실행 허용 필요.'],
['패키지 설치','최초 의존성 다운로드용 네트워크','버전·해시 잠금 의존성을 전용 .runtime 환경에 설치. 전역 Python은 변경하지 않음.']])+'''<p>전체 참조 검증 환경은 macOS와 Python 3.12입니다. 다른 OS에서 기본 검사를 시도할 수 있지만, 전체 격리 검증의 지원을 보장하지 않습니다.</p><p class="small">환경 도구: <a href="https://www.python.org/downloads/">Python 공식 다운로드</a> · <a href="https://docs.astral.sh/uv/getting-started/installation/">uv 공식 설치 안내</a>. 기관에서 승인한 설치 경로를 사용하세요.</p></section>
<section id="source"><h2>2. 고정 버전의 소스 받기</h2><p>가이드의 기준 소스는 공개 프리릴리스 <code>v0.10.0</code>입니다. 이전 버전에서 사용한 작업 폴더와 구분해 새 폴더에 받으세요. 이미 같은 이름의 폴더가 있다면 새 작업 경로를 사용하세요.</p>'''+get_source+'''<p><a href="'''+REPO+'''/archive/refs/tags/v0.10.0.zip">라이선스 포함 소스 ZIP 다운로드</a>도 가능합니다. 압축을 푼 경우 해당 폴더로 이동하세요. 검사 대상 저장소는 Git commit이 필요하지만, Harness 자체는 ZIP에서 실행할 수도 있습니다.</p><div class="note"><p>본 프로젝트와 이 가이드는 독립 저장소입니다. 가이드 수정에 서브모듈 갱신이 필요하지 않습니다. <a href="https://github.com/roboco-io/govcode-harness-guide">가이드 소스</a>의 버전 대응표에서 기준 코드를 확인할 수 있습니다.</p></div></section>
<section id="basic"><h2>3. 기본 흐름 먼저 확인하기</h2><p>프로젝트 루트에서 실행합니다. 명령은 새 합성 Git 저장소와 예시 자료를 출력 폴더 안에 만듭니다. 기존 업무 저장소는 수정하지 않습니다.</p>'''+basic+'''<p>정상 완료 시 명령의 종료 코드는 0이며 결과에는 <code>before: deny</code>, <code>after: allow</code>, <code>signature_status: not_signed</code>가 표시됩니다.</p><p>응답 보존, 민원 본문의 일반 로그 제거, 필요한 감사 호출 보존을 함께 확인합니다. 이 경로의 증적은 서명된 운영 증적이 아닙니다.</p></section>
<section id="reference"><h2>4. 서명과 관리까지 전체 참조 실행하기</h2><h3>전용 환경 설치</h3><p>아래 두 경로는 설치된 Python 3.12 이상과 uv의 실제 절대 경로로 바꾸세요. <code>command -v python3.12</code>와 <code>command -v uv</code>로 경로를 확인할 수 있습니다.</p>'''+setup+'''<p>버전·해시 잠금 파일에 따라 별도 환경을 만들고 정책·UI 자원을 포함한 Harness 패키지를 설치합니다. 기존 환경은 덮어쓰지 않습니다.</p><h3>새 출력 폴더에 실행</h3>'''+reference+'''<p>합성 작성자와 독립 승인자의 키 생성 → 예시 정책 서명 → 위험 commit 차단 → fixture 수정 제안과 승인 → 실제 OS 격리 검사 → 별도 알려진 수정 commit의 통과 → 증적 보관·복구 → 관리 API 확인 순서로 실행합니다.</p><div class="note"><p><strong>중요한 구분</strong> 격리된 제안 수정의 검사와 별도 알려진 수정 commit의 게이트 통과를 함께 확인하는 참조 흐름입니다. 실제 LLM이 자동으로 코드를 고쳐 운영 배포했다는 뜻이 아닙니다.</p></div></section>
<section id="preview"><h2>v0.10.0 프리뷰의 새 기능 실행하기</h2><p>위의 전용 환경 설치를 마친 뒤 아래 명령을 각각 실행하세요. 기존 전체 참조 데모 실행은 이 세 명령의 선행 조건이 아닙니다. 출력 폴더는 매번 새 경로를 사용합니다.</p><h3>사업 정보의 버전과 승인 확인</h3>'''+code('''.runtime/reference-venv/bin/python -m govcode_harness project profile-demo --output .runtime/onboarding-profile''')+'''<p>서로 다른 담당자의 승인으로 정보 두 버전을 만들고, 미확정 정보를 유지하며 자기 승인을 거부하는지 확인합니다. 결과 파일 <code>profile-demo-result.json</code>의 <code>active_revision</code>은 2, 확인 항목 6개는 모두 true가 기대 결과입니다.</p><h3>규정 묶음과 적용 대상 확인</h3>'''+code('''.runtime/reference-venv/bin/python -m govcode_harness project pack-demo --output .runtime/onboarding-pack''')+'''<p>서명된 규정 묶음의 발행·버전 고정, 독립 검토, 취소된 자료의 사용 거부를 확인합니다. 확인 항목 7개가 모두 true이고 최종 적용·제외·검토 필요 항목은 2·1·0입니다. 적용 대상 판단 완료는 요구 충족이나 운영 승인을 뜻하지 않습니다.</p><h3>설계 문서 초안 만들기</h3>'''+code('''.runtime/reference-venv/bin/python -m govcode_harness project document-kit --output .runtime/onboarding-documents''')+'''<p>PRD·아키텍처·데이터 모델·규정 추적 매트릭스·ADR·백로그와 AGENTS.md·작성 정책, 별도의 검토 메모를 만듭니다. 정보가 없으면 미제공으로 표시합니다. 생성 성공은 사실 검증이나 문서 승인이 아닙니다. AI Doc Ready를 자동 설치·실행하지 않으며 사실·수치·의미는 원문과 대조해야 합니다.</p><p><a href="'''+FILES+'''/docs/PROJECT_PROFILE_RUNBOOK.md">프로필 상세 안내</a> · <a href="'''+FILES+'''/docs/RULE_PACK_APPLICABILITY_RUNBOOK.md">규정 팩·적용성 안내</a> · <a href="'''+FILES+'''/docs/DOCUMENT_GENERATION.md">문서 생성과 선택적 구조 검사</a></p><p class="small">데모 출력에는 시험용 개인 키가 포함될 수 있습니다. 출력 폴더 전체를 공개하지 마세요.</p></section>
<section id="results"><h2>5. 결과를 읽고 성공 여부 확인하기</h2>'''+inspect+table(['항목','기대 결과·의미'],[
['before.outcome / after.outcome','deny / allow. 위험본과 수정본은 서로 다른 commit입니다.'],
['model_checks','verdict=verified, sandbox_verified=true, checks의 모든 값 true. backend=fixture, real_model_executed=false.'],
['store_checks / control_checks','각각 4개 / 5개의 확인 항목이 모두 true. 보관·복구와 실제 loopback API의 합성 역할 경계를 확인합니다.'],
['operational_approval / legal_records','false / pending. 실제 기관 승인과 법령 적용 판단을 대신하지 않습니다.']])+table(['종료 코드','처리'],[
['전체 참조 0','필수 합성 확인 완료. 실제 운영 승인으로 해석하지 않습니다.'],
['전체 참조 3','격리 불가 등으로 일부 필수 검증 미완료. 우회하여 완료 처리하지 않습니다.'],
['오류 4','설정·파일·정책 등 오류. 문제를 해결하고 새 출력 경로로 재실행합니다.'],
['scan / gate의 2 또는 3','각각 deny / review. 참조 데모의 완료 코드와 개별 판정 코드를 구분하세요.']])+'''<p>공유 가능한 요약은 <code>reference-result.json</code>입니다. 출력 폴더 전체를 업로드하지 마세요. 개인 키가 들어 있는 역할별 폴더(<code>author/</code>·<code>approver/</code>·<code>operator/</code>·<code>auditor/</code>)와 <code>control-bootstrap.json</code>, 로컬 설정은 공개 대상이 아닙니다.</p></section>
<section id="control"><h2>6. 로컬 관리 화면 열기</h2>'''+control+'''<p>명령이 표시하는 <a href="http://127.0.0.1:8766/">http://127.0.0.1:8766/</a>에 접속합니다. 터미널에서 서버를 실행한 상태로 유지하세요. 새 터미널 또는 로컬 편집기로 <code>control-bootstrap.json</code>의 필요한 역할 토큰을 확인해 화면에 입력합니다. 토큰을 채팅·이슈·화면 공유에 붙이지 마세요.</p>'''+table(['역할','확인할 기능'],[
['author','정책 초안·검토 제출·등록된 실행에 대한 예외 요청'],
['approver','다른 작성자가 제출한 정책·예외의 독립 승인'],
['operator','승인 정책 묶음 발급·보관 잠금 관리'],
['auditor','자기 기관·프로젝트의 실행·정책·증적 열람']])+'''<p>역할은 합성 참조 신원입니다. 운영 OIDC·LDAP 연결이 아닙니다. 데모 이후 화면은 복구한 보관소를 사용하므로 보존 잠금된 합성 증적을 확인할 수 있습니다. 종료하려면 서버 터미널에서 Ctrl+C를 누릅니다.</p><p><strong>GitHub Pages는 이 안내 사이트만 호스팅합니다.</strong> 검사 엔진·민원 API·관리 서버는 로컬 환경에서 실행합니다.</p></section>
<section id="ci"><h2>7. CI 적용을 준비하기</h2><p>먼저 로컬 시험과 게이트 사용법을 확인하세요.</p>'''+tests+'''<ul><li><code>ci/reference-gate.sh</code>는 기본 입력 게이트, <code>ci/reference-signed-gate.sh</code>는 서명 정책 참조 예제입니다.</li><li>신뢰한 전체 expected commit, 현재 HEAD, 증적 commit, 프로필과 receipt를 대조합니다. expected commit을 검사 대상 저장소의 사용자 파일에서 읽지 않습니다.</li><li>서명 묶음·신뢰 목록·기관·프로젝트·최소 순번과 철회 자료는 검사 checkout 밖의 신뢰 경로에서 제공합니다.</li><li>승인 예외는 정확한 commit·도구·정책·탐지 의미에 결합합니다. 오류·미분석·review를 예외로 통과시키지 않습니다.</li><li>과거 archive 무결성 성공을 현재 commit의 통과 결과로 재사용하지 않습니다.</li></ul><p>CI 예제는 비활성 상태입니다. 대상 저장소와 담당자를 정한 뒤 필수 검사와 보호 브랜치를 설정해야 실제 병합·배포를 막을 수 있습니다. 운영 중인 민원 요청을 차단하는 기능이 아닙니다.</p></section>
<section id="pilot"><h2>8. 기관 파일럿을 준비하기</h2><p>이 체크리스트는 준비 상태를 살펴보기 위한 도구입니다. 선택 결과는 저장되거나 전송되지 않으며 기관 승인 기록이 되지 않습니다.</p><p class="progress" data-progress role="status" aria-live="polite"></p><ul class="checklist">'''+checklist+'''</ul><p>권장 순서는 합성 데모 → 승인된 제한 저장소의 관찰 검사 → 독립 정답과 탐지·오탐·검토 부담 측정 → 기관 검토 후 필수 게이트 적용입니다. 일정·비용·성능을 미리 보장하지 않습니다.</p><p>법령상 확정 의무, 기관 정책, 예시 정책, 미확인 요구를 각각 기록하세요. 예시 정책을 운영 의무로 자동 승격하지 마세요. REG-LOG-008 등 미확정 법령 적용 항목은 원문·부칙·기준일 대조와 담당자 판단이 필요합니다.</p></section>
<section id="troubleshooting"><h2>문제 해결</h2>'''+table(['증상','조치'],[
['ENVIRONMENT_EXISTS_USE_EXISTING_OR_NEW_PATH','기존 환경을 사용하거나 설치 명령에 --environment .runtime/reference-new를 지정합니다. 이후 명령의 인터프리터 경로도 함께 바꿉니다.'],
['출력 폴더가 이미 있음','기존 결과를 보존하고 새로운 --output 경로로 실행합니다. 자동 덮어쓰기는 하지 않습니다.'],
['격리 불가 / undeterminable / exit 3','macOS의 sandbox-exec와 로컬 실행 권한을 확인합니다. 다른 OS 또는 제한 실행기에서 완전 성공을 표시하지 않습니다.'],
['crypto·jsonschema 모듈 없음','전용 참조 환경 설치가 완료됐는지 확인하고 .runtime/reference-venv/bin/python으로 실행합니다.'],
['관리 화면 401 / 403','현재 데모의 올바른 역할 토큰과 기관·프로젝트를 확인합니다. 다른 역할로 차단을 우회하지 않습니다.'],
['게이트 오류·commit 불일치','신뢰한 expected commit·현재 HEAD·증적·프로필을 대조하고 수정 후 새 commit을 검사합니다.'],
['포트가 이미 사용 중','--port로 사용하지 않는 로컬 포트를 지정하고 접속 주소도 같은 포트로 바꿉니다.']])+'''</section>
<section id="evidence"><h2>검증 근거와 자세한 자료</h2><p>v0.10.0 릴리스 검증 기록은 전체 시험 439개 통과, 실패·오류·건너뜀 0개를 보고합니다. 배포 패키지의 데모 실행과 생성 문서 8개의 구조 검사도 확인한 범위입니다. 실제 기관 운영이나 실제 AI의 답변 품질 검증을 뜻하지 않습니다.</p><p>문서 구조 검사와 사실·의미 검토를 구분합니다. 규정의 적용 대상 판단도 요구 충족 평가와 다릅니다. <a href="'''+FILES+'''/docs/VALIDATION.md">v0.10.0 검증 기록</a>과 <a href="'''+REPO+'''/releases/tag/v0.10.0">릴리스 노트</a>를 함께 확인하세요.</p><ul><li><a href="'''+FILES+'''/docs/REFERENCE_RUNBOOK.md">프로젝트 실행 안내</a></li><li><a href="'''+FILES+'''/docs/RALPH_COMPLETION_REPORT.md">구현·검증 보고서</a></li><li><a href="'''+FILES+'''/docs/R2_CORPUS.md">평가 표본과 분모 설명</a></li><li><a href="'''+FILES+'''/docs/EXTERNAL_READINESS.md">실제 운영 준비 조건</a></li><li><a href="'''+FILES+'''/docs/REVIEW_LEDGER.md">독립 검토와 수정 기록</a></li><li><a href="downloads/govcode-harness-brochure.pdf">도입 검토용 PDF 브로슈어</a></li></ul><p class="small">프로젝트 코드는 Apache-2.0, 이 가이드·브로슈어는 CC BY 4.0입니다. <a href="license.html">출처 표시 예와 라이선스 범위</a>를 확인하세요. 제3자 라이선스 표시는 유지합니다.</p></section></article></div></main>''')

    page('brochure.html','도입 브로슈어','보안이 내재화된 개발 하네스, GovCode Harness. 개발팀·검토자·프로젝트 책임자를 위한 가치와 첫 도입 경로를 소개합니다.',
'''<main id="main"><div class="wrap brochure-tools"><div><h1 style="font:700 1.25rem/1.5 -apple-system,BlinkMacSystemFont,sans-serif;margin:0">도입 검토용 브로슈어</h1><p class="small" style="margin:3px 0 0">웹으로 읽거나 A4 2쪽 PDF로 공유하세요.</p></div><div class="actions"><a class="button" href="downloads/govcode-harness-brochure.pdf" download>PDF 다운로드</a><button class="button secondary" type="button" data-print>인쇄</button></div></div><div class="brochure">
<section class="sheet" aria-label="브로슈어 1쪽"><a class="brand" href="https://roboco.io/govcode-harness-guide/"><span class="mark" aria-hidden="true">G</span>GovCode Harness</a><h1>보안이 내재화된<br>개발 하네스</h1><p class="deck">개발 과정에 보안 점검과 검토를 함께 연결합니다.<br>무엇을 고쳤고 누가 확인했는지 기록으로 남깁니다.</p>'''+platform_flow()+'''<div class="columns"><div class="feature"><h3>다음 행동을 안내합니다</h3><p>개발자가 문제를 찾아 고치고 다시 점검하도록 돕습니다.</p></div><div class="feature"><h3>판단 근거를 연결합니다</h3><p>검토자가 점검 기준과 결과, 승인 기록을 확인합니다.</p></div><div class="feature"><h3>진행을 확인합니다</h3><p>첫 사례의 처리 과정을 보고, 전체 업무 현황 안내로 확장합니다.</p></div></div><div class="band"><p><strong>개발과 보안 검토가 같은 흐름, 같은 근거 위에서 이어지도록.</strong><br>하네스는 개발 도구와 점검 절차를 함께 작동하게 연결하는 장치입니다.</p></div><p class="small">현재는 시험·개선 중인 파일럿 단계입니다. 프로젝트 코드는 Apache-2.0 조건에 따라 무상으로 사용·수정·재배포할 수 있습니다. 시험용 가상 자료로 확인했으며 실제 기관 시험 운영은 완료하지 않았습니다.</p><div class="sheet-foot"><span>© 2026 GovCode Harness contributors · <a rel="license" href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a></span><span>roboco.io/govcode-harness-guide/ · 1 / 2</span></div></section>
<section class="sheet" aria-label="브로슈어 2쪽"><span class="tag">설치 없이 이해하고 의견 남기기</span><h2 style="margin-top:20px">다양한 공공 업무의 제작 기반을 살펴보세요.</h2><p>비개발자가 AI와 업무 도구를 직접 만드는 것이 목표입니다. 이번 프리뷰는 사업 정보를 승인하고, 적용할 규정 묶음을 정하며, 설계 문서 초안을 만드는 기반을 확장했습니다.</p><p class="small">공개 태그는 v0.10.0입니다. 적용 대상 판단이나 문서 생성 성공은 요구 충족·운영 승인·법적 준수 인증을 뜻하지 않습니다.</p><ol class="steps"><li><span class="step-num">1</span><div><h3>설명과 화면을 살펴보세요</h3><p>쉬운 안내에서 도구의 역할과 시험용 화면을 읽어 보세요.</p></div></li><li><span class="step-num">2</span><div><h3>우리 업무에 필요한 점을 생각해 보세요</h3><p>빠뜨리기 쉬운 점검, 검토할 때 필요한 자료를 떠올려 주세요.</p></div></li><li><span class="step-num">3</span><div><h3>의견을 남겨 주세요</h3><p>개발 경험이 없어도 참여할 수 있습니다. GitHub 계정으로 로그인해 공개 의견을 남깁니다.</p></div></li><li><span class="step-num">4</span><div><h3>직접 실행은 개발 담당자와 함께</h3><p>설치·실행 안내를 개발 담당자에게 전달하고 시험 범위를 정하세요.</p></div></li></ol><div class="note"><p><strong>v0.10.0 프리뷰: 사업 정보·규정 묶음·문서 초안</strong><br>후속 점검 분야: 개인정보·보안, 접근성, 개발 품질, 표준·상호운용성,<br>사업 수행·산출물, 운영·기록·보존. 적용 여부는 프로젝트별로 확인합니다.</p></div><p class="small">현재는 일부 Python 코드와 macOS 환경에서 확인한 시험 버전입니다. AI는 미리 준비한 응답으로 동작을 시험했습니다. 실제 기관 적용과 AI 답변 품질은 별도 확인이 필요합니다.</p><div><h3>쉬운 안내부터 시작하세요</h3><p><a href="'''+URL+'''start.html">roboco.io/govcode-harness-guide/start.html</a><br><a href="'''+TAG+'''">github.com/roboco-io/govcode-harness · Apache-2.0</a><br><a href="'''+URL+'''community.html">의견·참여: community.html</a> · <a href="'''+URL+'''updates.html">개발 상황: updates.html</a></p></div><div class="sheet-foot"><span>roboco-io / GovCode Harness contributors · <a rel="license" href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a></span><span>파일럿 · 코드 Apache-2.0 · 실행·운영 비용 별도 · 2 / 2</span></div></section></div></main>''')
    page('start.html','처음 읽는 쉬운 안내','개발 경험 없이 GovCode Harness의 역할, 민원 점검 사례, 파일럿 참여 방법을 알아보세요. 설치 없이 읽을 수 있습니다.',
        '''<main id="main" class="wrap"><header class="page-head"><span class="tag">설치 없이 읽는 쉬운 안내</span><h1>우리 업무에 어떤 도움이 될까요?</h1><p>GovCode Harness의 목표는 다양한 공공 프로젝트에서 비개발자가 AI와 함께 업무 도구를 안전하게 만드는 것입니다. v0.10.0 프리뷰는 사업 정보, 규정 묶음, 설계 문서와 점검 기록을 연결하는 기반을 제공합니다.</p></header><div class="guide-grid"><nav class="toc" aria-label="쉬운 안내 목차"><strong>궁금한 내용부터 읽으세요</strong><a href="#purpose">어떤 도구인가요?</a><a href="#example">민원 처리 사례</a><a href="#today">지금 가능한 것</a><a href="#next">내 역할에 맞는 다음 단계</a><a href="#words">낯선 말 풀이</a><a href="#questions">자주 묻는 질문</a></nav><article class="article"><section id="purpose"><h2>보안이 개발 과정에 들어간다는 뜻</h2><p>프로그램을 만들거나 고칠 때, 정해 둔 보안 기준에 맞는지 함께 확인한다는 뜻입니다. 문제가 있으면 개발자가 고치고 다시 검사합니다. 검토 담당자는 그 결과를 보고 승인하며, 무엇을 확인했는지 기록을 남깁니다.</p><p>‘하네스’는 이 도구들과 절차를 연결해 함께 작동하게 하는 장치를 뜻합니다. 사람마다 따로 하던 점검과 검토를 이어 주는 역할입니다.</p></section><section id="example"><h2>예를 들어, 민원 내용이 불필요한 기록에 남는다면?</h2><p>다음은 가상 민원 자료로 확인한 첫 사례입니다. 여기서 ‘로그’는 프로그램이 작업하면서 남기는 기록입니다.</p><ol class="steps"><li><span class="step-num">1</span><div><h3>문제를 찾습니다</h3><p>민원 원문을 일반 작업 기록에 남기는 코드가 있는지 점검합니다. 위험이 발견되면 해당 코드는 검사를 통과하지 못합니다.</p></div></li><li><span class="step-num">2</span><div><h3>개발자가 수정 결과를 확인합니다</h3><p>민원 원문을 불필요하게 남기지 않도록 고친 코드를 다시 검사합니다. 민원 응답과 필요한 감사 기록이 유지되는지도 확인합니다.</p></div></li><li><span class="step-num">3</span><div><h3>검토할 자료를 남깁니다</h3><p>어떤 기준으로 무엇을 확인했는지, 수정 전후 결과가 어땠는지 연결해 둡니다. 이를 확인 자료인 ‘증적’이라고 부릅니다.</p></div></li></ol><p>이 사례는 프로그램 코드를 점검합니다. 접수 중인 실제 민원 요청을 막는 기능은 아닙니다.</p></section><section id="today"><h2>지금은 어디까지 만들어졌나요?</h2><div class="boundaries"><div><h3>현재 확인한 것</h3><p>시험용 민원 프로그램의 문제 발견·수정 후 재점검, 담당자 승인, 확인 자료의 보관·복구와 한국어 관리 화면을 가상 자료로 확인했습니다.</p></div><div><h3>새 프리뷰와 다음 단계</h3><p>v0.10.0에는 사업 정보 관리, 규정 묶음의 적용 대상 판단과 설계 문서 초안 생성이 포함됐습니다. 자연어로 설명해 도구를 만들고 실행하는 전체 경험, 여러 분야의 실제 점검과 전체 완료 현황은 후속 범위입니다. <a href="updates.html">자세한 개발 상황</a></p></div></div><p><strong>현재는 파일럿, 즉 시험하고 개선하는 단계입니다.</strong> 실제 기관에서의 시험 운영은 완료하지 않았습니다. 실제 업무에 쓰려면 개발·보안 담당자의 검토가 필요합니다.</p><figure style="margin:24px 0"><img class="screenshot" src="assets/images/control-desk.png" alt="시험용 관리 화면 예시. 점검 실행 결과와 확인 자료를 열람하는 메뉴가 있습니다." width="1440" height="1000" loading="lazy"><figcaption class="caption">가상 자료로 만든 관리 화면입니다. 이 웹사이트에서 직접 조작하는 체험 화면은 아닙니다.</figcaption></figure></section><section id="next"><h2>내 역할에 맞게 참여하세요</h2><ul><li><strong>사업·기획 담당자:</strong> 우리 업무에서 빠뜨리기 쉬운 점검과 남겨야 할 자료를 떠올려 주세요. 필요한 기능을 의견으로 남길 수 있습니다.</li><li><strong>보안·검토 담당자:</strong> 어떤 기준과 확인 자료가 있어야 판단할 수 있는지 알려 주세요.</li><li><strong>개발 담당자:</strong> <a href="onboarding.html">설치·실행 안내</a>로 시험용 프로그램을 실행하고 결과를 확인하세요.</li></ul><p>개발 경험이 없어도 설명이 어려웠던 부분이나 개선 아이디어를 알려 주시면 됩니다. <a href="brochure.html">소개 자료</a>를 동료에게 공유해 함께 검토해도 좋습니다.</p><div class="actions"><a class="button" href="community.html">의견 남기는 방법 보기</a><a class="button secondary" href="downloads/govcode-harness-brochure.pdf" download>소개 자료 PDF 받기</a></div></section><section id="words"><h2>낯선 말은 이렇게 이해하세요</h2><dl><dt><strong>보안이 내재화된 개발</strong></dt><dd>프로그램을 만드는 과정에 보안 점검과 검토 절차가 포함된 개발 방식입니다.</dd><dt><strong>정책</strong></dt><dd>검사에 사용할 기준과 처리 규칙입니다. 예시로 만든 정책과 실제 기관의 승인된 기준은 구분합니다.</dd><dt><strong>증적</strong></dt><dd>무엇을 검사하고 검토했는지 보여 주는 결과와 기록입니다.</dd><dt><strong>합성 자료</strong></dt><dd>시험을 위해 만든 가상 자료입니다. 실제 민원인의 정보를 사용하지 않습니다.</dd><dt><strong>규정 팩</strong></dt><dd>한 분야의 기준과 할 일, 점검 항목을 묶은 구성입니다. 발행·버전 고정·적용 대상 판단은 v0.10.0 프리뷰에 포함됐습니다. 실제 요구 충족 검사는 별도 기능입니다.</dd><dt><strong>오픈소스</strong></dt><dd>정해진 라이선스 조건에 따라 소스 코드를 보고 사용·수정·공유할 수 있는 소프트웨어입니다.</dd></dl></section><section id="questions"><h2>자주 묻는 질문</h2><h3>직접 설치해야 의견을 낼 수 있나요?</h3><p>설명이나 화면 예시를 읽어 본 의견만 남겨도 좋습니다. 직접 실행은 개발 담당자가 <a href="onboarding.html">설치·실행 안내</a>를 따라 진행할 수 있습니다.</p><h3>비용이 드나요?</h3><p>프로젝트 코드는 Apache-2.0 조건에 따라 라이선스 비용이나 로열티 없이 사용할 수 있습니다. 설치·인프라·운영 비용은 사용 환경에 따라 발생할 수 있습니다. <a href="license.html">자세한 사용 조건</a>을 확인하세요.</p><h3>검사를 통과하면 모든 보안 요구를 충족하나요?</h3><p>통과는 해당 검사 범위에서 확인한 결과입니다. 모든 보안 요구 충족이나 법적 준수 인증을 뜻하지 않습니다. 기관별 적용 판단과 운영 승인은 담당자가 검토해야 합니다.</p><h3>AI가 알아서 수정하고 승인하나요?</h3><p>AI는 설명과 수정안을 제안하는 역할입니다. 담당자의 승인과 별도 검사가 필요합니다. 현재 시험에서는 미리 준비한 AI 응답을 사용하며 실제 AI의 답변 품질은 아직 확인하지 않았습니다.</p></section></article></div></main>''')
    page('community.html','의견 남기기와 참여 방법','파일럿 단계의 GovCode Harness를 체험하고 피드백·버그·기능 제안·코드와 문서 기여로 참여하세요.',
        '''<main id="main" class="wrap"><header class="page-head"><span class="tag">파일럿 단계 · 함께 만드는 개발 하네스</span><h1>써 본 경험이,<br>다음 개발 흐름이 됩니다.</h1><p>개발 경험이 없어도 참여할 수 있습니다. 설명을 읽고 이해하기 어려웠던 점, 우리 업무에 필요하다고 느낀 기능을 알려 주세요.</p></header><article class="article" style="padding-bottom:60px"><section><h2>부담 없이 시작하세요</h2><p>본 프로젝트 코드는 Apache-2.0 조건에 따라 라이선스 비용이나 로열티 없이 사용할 수 있습니다. 상업적 이용·수정·재배포도 가능합니다. 현재는 합성 자료 검증을 제공하는 파일럿 단계이며 실제 기관 파일럿 완료를 뜻하지 않습니다.</p><p>라이선스의 재배포 조건과 무보증 조항을 따릅니다. 설치·인프라·운영 비용은 별도입니다. 이 가이드와 브로슈어는 CC BY 4.0입니다. <a href="license.html">라이선스 안내</a></p></section><section id="send-feedback"><h2>처음 의견을 남기신다면</h2><p>의견은 소스 코드와 협업 내용을 공유하는 사이트인 <strong>GitHub(깃허브)</strong>에서 받습니다. ‘이슈’는 문제나 제안을 적는 게시글입니다. 작성하려면 GitHub 계정으로 로그인해야 하며, 게시한 내용은 누구나 볼 수 있습니다.</p><ol><li>아래 <strong>파일럿 피드백</strong> 링크를 눌러 GitHub로 이동합니다.</li><li>로그인한 뒤, 살펴본 내용과 도움이 된 점 또는 막힌 점을 적습니다. 실행하지 않았다면 읽은 페이지 주소만 적어도 좋습니다.</li><li>개인정보나 기관 내부 자료가 없는지 확인하고 제출 버튼을 누릅니다. 제출 후에는 해당 게시글에서 답변과 진행 상황을 확인할 수 있습니다.</li></ol><p><strong>이 정도의 의견이면 충분합니다.</strong></p><blockquote><p>소개 자료를 읽었습니다. 사업 담당자가 점검 결과에서 무엇을 확인해야 하는지 예시가 있으면 좋겠습니다.</p></blockquote><p>지금 계정을 만들기 어렵다면 <a href="brochure.html">소개 자료</a>를 동료에게 공유하고 함께 의견을 정리해 두세요.</p></section><section><h2>어디에 남기면 될까요?</h2><p>이미 같은 의견이 있다면 기존 게시글에 보태 주세요. 새 의견은 아래 양식에서 남길 수 있습니다.</p><div class="boundaries"><div><h3>프로젝트 사용·실행 의견</h3><p>검사 엔진, 정책, 관리 화면, 실행 결과와 향후 기능에 관한 의견을 받습니다.</p><p><a href="https://github.com/roboco-io/govcode-harness/issues/new?template=01-feedback.yml">파일럿 피드백</a> · <a href="https://github.com/roboco-io/govcode-harness/issues/new?template=02-bug.yml">버그 보고</a> · <a href="https://github.com/roboco-io/govcode-harness/issues/new?template=03-improvement.yml">개선 제안</a></p></div><div><h3>가이드·브로슈어 의견</h3><p>설명, 명령 안내, 링크, 웹 화면과 PDF에서 개선할 점을 알려 주세요. 실행 경험 없이 읽어 본 의견만 남겨도 좋습니다.</p><p><a href="https://github.com/roboco-io/govcode-harness-guide/issues/new/choose">가이드 의견 남기기</a></p></div></div></section><section><h2>이렇게 적어 주세요</h2><ol><li>살펴본 버전이나 페이지 URL, 사용 환경과 시도한 작업을 적어 주세요.</li><li>도움이 된 점 또는 기대와 달랐던 점을 알려 주세요.</li><li>버그는 합성 입력과 재현 절차를, 제안은 해결할 문제와 기대 결과를 적어 주세요.</li></ol><p>기관 이름과 연락처를 공개할 필요는 없습니다. 개인정보·내부 자료·원본 로그·토큰·개인 키는 첨부하지 마세요. 악용 가능한 취약점 세부 내용도 공개 이슈에 올리지 마세요.</p></section><section><h2>문서나 코드를 직접 고치고 싶다면</h2><p>이 절차는 직접 파일을 수정할 분을 위한 안내입니다. PR(변경 제안)은 수정한 내용을 프로젝트에 반영해 달라는 요청입니다.</p><ol><li>작은 문구 수정은 바로 PR을 보내 주세요. 큰 기능 변경은 이슈에서 문제와 범위를 먼저 설명해 주세요.</li><li>저장소를 fork하고 작업 브랜치에서 한 가지 목적의 변경을 만드세요.</li><li>기여 안내의 검증을 수행하고 결과·미검증 범위를 PR 템플릿에 적어 주세요.</li></ol><p><a href="https://github.com/roboco-io/govcode-harness/blob/main/CONTRIBUTING.md">프로젝트 기여 안내</a> · <a href="https://github.com/roboco-io/govcode-harness-guide/blob/main/CONTRIBUTING.md">가이드 기여 안내</a></p><p class="small">제출할 권한이 있는 자료만 포함하고 출처와 라이선스를 표시해 주세요. 응답 시점과 구현 일정은 확정되어 있지 않습니다.</p></section></article></main>''')
    page('updates.html','v0.10.0 프리뷰 업데이트','프로젝트 정보·규정 팩·적용 대상 판단·설계 문서 초안 생성이 포함된 공개 프리뷰를 안내합니다.',
        '''<main id="main" class="wrap"><header class="page-head"><span class="tag">공개일: 2026-10-30 KST · 프리릴리스</span><h1>v0.10.0 프리뷰가<br>공개됐습니다.</h1><p>다양한 공공 프로젝트에서 비개발자가 안전하게 바이브 코딩을 하도록 돕는 기반을 확장했습니다. 프로젝트 정보 관리, 규정 묶음 발행·적용 대상 판단, AI 친화적 설계 문서 초안 생성이 이번 공개 버전에 포함됐습니다.</p></header><article class="article" style="padding-bottom:60px"><section><h2>이번에 추가된 기능</h2><ul><li><strong>프로젝트 정보 관리:</strong> 사업 특성과 확인한 정보를 버전별로 남기고 다른 담당자가 승인합니다. 모르는 정보는 미확정으로 유지합니다.</li><li><strong>규정 묶음 발행과 버전 고정:</strong> 분야별 기준 묶음을 검토·승인하고 사용할 정확한 버전을 지정합니다. 만료·철회와 의존 관계를 검증합니다.</li><li><strong>적용 대상 판단:</strong> 기준을 적용·제외·검토 필요로 구분합니다. 제외 판단과 법적 근거의 적용에는 독립 검토가 필요합니다.</li><li><strong>설계 문서 초안 생성:</strong> 공통 작성 정책에 따라 PRD·아키텍처·데이터 모델·규정 추적 매트릭스·ADR·백로그와 AGENTS.md·작성 정책을 만듭니다. 검토 메모는 분리합니다.</li></ul><p>기존 로깅 위험 점검·수정 후 재검사, 정책 승인·증적 보관·관리 화면도 유지합니다. 민원 로깅은 첫 기술 검증 사례이며 제품의 적용 업무를 한정하지 않습니다.</p></section><section><h2>어디서 시작하나요?</h2><p>정확한 태그는 <code>v0.10.0</code>이며 GitHub에서 프리릴리스로 표시됩니다. 새 폴더에 이 태그를 받아 <a href="onboarding.html#preview">프로필·규정 팩·문서 생성 안내</a>를 따라 시험할 수 있습니다.</p><p><a href="https://github.com/roboco-io/govcode-harness/releases/tag/v0.10.0">릴리스 노트와 배포 파일</a> · <a href="https://github.com/roboco-io/govcode-harness/tree/v0.10.0">고정 버전 소스</a></p></section><section><h2>아직 준비 중인 경험</h2><p>비개발자의 자연어 요구 설명부터 AI와 제작·실행·공유까지 이어지는 전체 사용자 경험은 아직 완성되지 않았습니다. 추가 산출물 검사·요구 충족 평가·새 단계 게이트와 관리 화면 확장은 후속 범위입니다.</p><p>규정 적용 대상이 정해졌다는 것이 그 기준을 충족했다는 뜻은 아닙니다. 문서 생성 성공도 사실 검증이나 승인이 아닙니다. AI Doc Ready는 자동 설치·실행되지 않으며 구조 검사와 별도로 사실·수치·의미를 검토해야 합니다.</p></section><section><h2>검증 기록과 주의할 경계</h2><p>릴리스 검증 기록은 전체 시험 439개 통과, 실패·오류·건너뜀 0개를 보고합니다. 배포 패키지의 실제 데모와 생성 문서 8개의 구조 검사도 확인했습니다. 이는 가상 자료를 사용한 참조 구현의 검증이며 실제 기관 파일럿 완료나 법적 준수 인증이 아닙니다.</p><p><a href="https://github.com/roboco-io/govcode-harness/blob/v0.10.0/docs/VALIDATION.md">해당 릴리스의 검증 기록</a> · <a href="https://github.com/roboco-io/govcode-harness/blob/v0.10.0/docs/DOCUMENT_GENERATION.md">문서 생성 안내</a></p><p class="small">확인한 태그의 커밋: <a href="https://github.com/roboco-io/govcode-harness/commit/7d60fdb677b6792cf6b7dd451a3b87a6d038fa91">7d60fdb</a>. 이전 v0.9.0의 320개·개발 중간 단계의 431개 기록은 과거 검증 기록입니다.</p></section></article></main>''')
